        } catch (e) {
          return json(res, 404, { error: "找不到这份历史" });
        }
      }

      // 某份历史 vs 当前版本的差异
      if (req.method === "GET" && p === "/diff") {
        const safe = path.basename(q.get("name") || "");
        if (!safe) return json(res, 400, { error: "缺少 name" });
        let old = "";
        try {
