  //
  // dispose 是幂等的（数组已空、null 直接跳过），万一调用方同时拿到返回值也不会出事。
  if (typeof ctx.effect === "function") {
    ctx.effect(() => dispose, "@gw/dsh-text-inject");
  }
  return dispose;
}
